"""Turns a finished run into things a person can hand on: a markdown brief, a printable one-page HTML and an
email draft. Drafts only. Nothing here sends anything."""
import html


def _facts_by_id(res):
    return {f["id"]: f for f in res.get("facts", [])}


def render_markdown(res):
    b, co = res["brief"], res["company"]
    L = ["# Competitor read: %s" % co["name"], "",
         "_Window: %s to %s. Built from public profile data; every number below is a fact with a source. "
         "Generated by Org Chart X-Ray (%s)._" % (res["window"]["start"], res["window"]["end"], b["generated_by"]), "",
         "## Headline", b["headline"], ""]
    if b.get("inference"):
        L += ["## What this suggests (%s confidence, an inference)" % b["inference"]["confidence"], b["inference"]["text"], ""]
    L += ["## Findings"]
    for f in b["findings"]:
        L.append("- %s [%s]" % (f["text"], ", ".join(f["fact_ids"])))
    if b.get("actions"):
        L += ["", "## What to do"] + ["- " + x for x in b["actions"]]
    sn = (res["analysis"].get("senior") or {}).get("list") or []
    if sn:
        L += ["", "## Senior hires (Director and above)"]
        for s in sn[:10]:
            L.append("- %s, %s: joined %s%s" % (s["name"], s["title"], s["start"], " from " + s["prev"] if s.get("prev") else ""))
    L += ["", "## What we removed or cannot see"] + ["- " + x for x in b["caveats"]]
    L += ["", "## Sources"]
    for f in res["facts"]:
        L.append("- %s: %s" % (f["id"], f["source"]))
    L += ["", "_Credits used for this run: %s. Data as of the headcount series date shown above._" % res.get("credits")]
    return "\n".join(L)


def email_draft(res):
    b, co = res["brief"], res["company"]
    c = res["analysis"]["counts"]
    ex = res["analysis"].get("exits")
    top = [d for d in res["analysis"]["depts"] if d["name"] != "Unplaced"][:2]
    subject = "Competitor read: %s hiring since %s" % (co["name"], res["window"]["start"][:7])
    lines = ["Hi [name],", "",
             "Quick read on %s from public hiring data (%s to %s):" % (co["name"], res["window"]["start"], res["window"]["end"]), "",
             "- %d real external hires (we removed %d re-recorded roles that look like hires but are not)." % (c["external"], c["relisted"])]
    if top:
        lines.append("- Biggest teams: " + ", ".join("%s (%d)" % (d["name"], d["external"]) for d in top) + ".")
    if ex:
        lines.append("- %d people left, so net tracked change is %+d." % (ex["left"], ex["net_total"]))
    if b.get("inference"):
        lines.append("- Read: " + b["inference"]["text"])
    lines += ["", "Caveats: public data lags by up to a month, shows no reporting lines or plans, and some people have no "
              "team tag. Full brief with sources attached.", "", "[your name]", "",
              "(Draft only. Nothing has been sent.)"]
    return "Subject: %s\n\n%s" % (subject, "\n".join(lines))


def render_html(res):
    e = html.escape
    b, co = res["brief"], res["company"]
    sn = (res["analysis"].get("senior") or {}).get("list") or []
    rows = "".join("<tr><td>%s</td><td>%s</td><td>%s</td><td>%s</td></tr>" % (
        e(s["name"] or ""), e(s["title"] or ""), e(s["start"]), e(s.get("prev") or "-")) for s in sn[:8])
    return """<!doctype html><html lang="en"><head><meta charset="utf-8"><title>%(t)s</title><style>
@page{size:A4;margin:14mm}body{font:12.5px/1.45 system-ui,Segoe UI,Arial,sans-serif;color:#111;max-width:760px;margin:0 auto;padding:16px}
h1{font-size:20px;margin:0 0 2px}h2{font-size:12px;text-transform:uppercase;letter-spacing:.6px;color:#555;margin:14px 0 4px}
.sub{color:#555;font-size:11.5px}.inf{background:#eef2ff;padding:8px 10px;border-radius:6px}ul{margin:4px 0 4px 18px;padding:0}
table{width:100%%;border-collapse:collapse;font-size:11.5px}td,th{border-bottom:1px solid #ddd;padding:3px 6px;text-align:left}
.cav{background:#fff4dc;padding:6px 10px;border-radius:6px;font-size:11.5px}.src{font-size:10.5px;color:#555}
button{margin-bottom:8px}@media print{button{display:none}}</style></head><body>
<button onclick="print()">Print or save as PDF</button>
<h1>Competitor read: %(co)s</h1><div class="sub">Window %(ws)s to %(we)s · public profile data · every number has a source below · %(gen)s</div>
<h2>Headline</h2><div><b>%(head)s</b></div>%(inf)s
<h2>Findings</h2><ul>%(find)s</ul>
%(actions)s
%(senior)s
<h2>What we removed or cannot see</h2><div class="cav"><ul>%(cav)s</ul></div>
<h2>Sources</h2><div class="src">%(src)s</div></body></html>""" % {
        "t": e("Competitor read: " + co["name"]), "co": e(co["name"]), "ws": e(res["window"]["start"]), "we": e(res["window"]["end"]),
        "gen": e(b["generated_by"]), "head": e(b["headline"]),
        "inf": ('<h2>What this suggests (%s confidence, an inference)</h2><div class="inf">%s</div>' % (
            e(b["inference"]["confidence"]), e(b["inference"]["text"]))) if b.get("inference") else "",
        "find": "".join("<li>%s <span class='src'>[%s]</span></li>" % (e(f["text"]), e(", ".join(f["fact_ids"]))) for f in b["findings"]),
        "actions": ("<h2>What to do</h2><ul>%s</ul>" % "".join("<li>%s</li>" % e(x) for x in b["actions"])) if b.get("actions") else "",
        "senior": ("<h2>Senior hires</h2><table><tr><th>Name</th><th>Title</th><th>Joined</th><th>From</th></tr>%s</table>" % rows) if rows else "",
        "cav": "".join("<li>%s</li>" % e(x) for x in b["caveats"]),
        "src": "<br>".join("%s: %s" % (e(f["id"]), e(f["source"])) for f in res["facts"])}
